import{_ as s,l as n,o as e,c as o,v as t,p as l,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"分布式追踪","description":"","frontmatter":{"title":"分布式追踪","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/distributed-tracing.md","filePath":"cs/distributed-tracing.md","lastUpdated":1789023840000}'),h={name:"cs/distributed-tracing.md"};function _(u,a,m,T,f,A){const i=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="分布式追踪" tabindex="-1">分布式追踪 <a class="header-anchor" href="#分布式追踪" aria-label="Permalink to &quot;分布式追踪&quot;">​</a></h1><div class="epigraph"><p>一次请求跨许多进程，把因果边采成 span 树。采样与传播头让你看见扇出，不是代替[向量时钟](/cs/vector-clocks)的完备偏序。</p><footer>—— 据 Sigelman et al., Dapper, a Large-Scale Distributed Systems Tracing Infrastructure, Google 技术报告 2010 整理</footer></div><p>上一课<a href="/cs/lb-strategies">负载均衡</a>把请求打散。缺口是<strong>一次用户调用变成哪些 RPC</strong>：过载与错误发生在哪一跳。本课钉 Dapper 式追踪：trace id、span、采样。后课三支柱把日志与指标接上。不重写 happened-before 定理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Dapper：前端生成 trace id，沿 RPC 传播；每跳一个 span，父子边是调用。采样：全量太贵，按树决策（根决定采不采）保持一棵树完整。缺口：追踪是调试与容量的观察，不是线性一致证明。时钟用墙钟画甘特，跨机可能倒序——接<a href="/cs/clock-drift">时钟漂移</a>，边靠传播的父子关系，不靠 NTP。</p><p>与日志：日志无跨进程 id 则拼不出树。与指标：指标无单次请求。</p><p><span class="marginnote">2010 技术报告是工业源头。OpenTelemetry 是后来的 API 收敛，本课点名不写规范全书。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>埋点在 RPC 桩与队列消费者：取出/注入上下文。异步消息要把 trace 放进消息头，否则 Saga 步骤断链。采样率可动态，错误路径可强制采。</p>',9)),(e(),l(c,null,{default:r(()=>[d(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A0%B9%20span%22%5D%20--%3E%20A%5B%22%E6%9C%8D%E5%8A%A1%20A%22%5D%0A%20%20ROOT%20--%3E%20B%5B%22%E6%9C%8D%E5%8A%A1%20B%22%5D%0A%20%20A%20--%3E%20C%5B%22%E5%AD%98%E5%82%A8%22%5D%0A%20%20CTX%5B%22trace%20%E4%B8%8A%E4%B8%8B%E6%96%87%E4%BC%A0%E6%92%AD%22%5D%20--%3E%20ROOT%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要只在成功路径埋点。失败跳往往没 span，最需要看。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Head-based 采样：根决定，便宜，可能漏稀有错误。Tail-based：先全量收再决定留哪些，贵，能留异常树。生产常混合。高基数标签（user id）会把追踪后端打成热键——接上一课序。</p><p>本课不写 Zipkin 全部 UI。也不把追踪当安全审计完整解（缺不可伪造）。</p><p>因果：span 父子 ⊂ happened-before，但未埋点的边看不见。不能用追踪图当 Chandy–Lamport 快照。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把指标仪表盘画全。后课默认：跨服务排障先跟 trace id；时钟只用来显示，边用传播。可观测三支柱下一课说明三者不可互相替代。</p><p>看见扇出才能解释 P99。看不见的边等于不存在于调试里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Trace/span 树靠上下文传播，不靠 NTP 排序。</li><li>采样保整树；错误路径要能强制采。</li><li>观察工具不是一致性证明。</li><li>出处：Sigelman et al., Dapper, 2010。</li></ul>',10))])}const P=s(h,[["render",_]]);export{E as __pageData,P as default};
